            C#

    // C# program for the
// above approach
using System;
using System.Collections.Generic;
class GFG {

    // Function to return maximum
    // MEX of all K length subarray
    static void maxMEX(int[] arr, int N, int K)
    {
        // Stores element from
        // 1 to N + 1 is nor
        // present in subarray
        HashSet<int> s = new HashSet<int>();

        // Store number 1 to
        // N + 1 in set s
        for (int i = 1; i <= N + 1; i++)
            s.Add(i);

        // Find the MEX of K length
        // subarray starting from index 0
        for (int i = 0; i < K; i++)
            s.Remove(arr[i]);

        List<int> v = new List<int>();
        foreach(int i in s) { v.Add(i); }
        int mex = v[0];

        // Find the MEX of all subarray of
        // length K by erasing arr[i]
        // and inserting arr[i-K]
        for (int i = K; i < N; i++) 
        {
            v.Remove(arr[i]);
            v.Add(arr[i - K]);

            // Store first element
            // of set
            int firstElem = v[0];

            // Updating mex
            mex = Math.Max(mex, firstElem);
        }

        // Print maximum MEX of all K
        // length subarray
        Console.Write(mex - 2 + " ");
    }

    // Driver Code
    public static void Main(String[] args)
    {
        // Given array
        int[] arr = { 3, 2, 1, 4 };

        // Given length of subarray
        int K = 2;

        // Size of the array
        int N = arr.Length;

        // Function Call
        maxMEX(arr, N, K);
    }
}

